import{_ as d,l as c,o as e,c as s,v as r,p as A,x as o,d as l,i,S as n}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"ARM AArch64","description":"","frontmatter":{"title":"ARM AArch64","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/aarch64-isa.md","filePath":"cs/aarch64-isa.md","lastUpdated":1789023840000}'),h={name:"cs/aarch64-isa.md"};function p(E,a,R,S,_,m){const t=c("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="arm-aarch64" tabindex="-1">ARM AArch64 <a class="header-anchor" href="#arm-aarch64" aria-label="Permalink to &quot;ARM AArch64&quot;">​</a></h1><div class="epigraph"><p>A64 定长 32 位，31 个通用寄存器加零寄存器，load/store，条件码与可选的条件执行残留在比较与分支上，而不是 x86 那种变长外壳。</p><footer>—— 据 ARM Architecture Reference Manual for A-profile；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/x86-microcode-decode">上一课</a>展示了 CISC 前端税。缺口是另一条工业主线 <strong>AArch64</strong>：定长、宽寄存器堆，作为后课与 RISC-V 对比的一端。不把 ARMv7 Thumb 变长当本课主体。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>A64：4 字节对齐指令，<code>Xn</code>/<code>Wn</code>，<code>XZR</code>/<code>WZR</code> 读零写丢弃（类似 <code>x0</code>）。寻址：基址+偏移、预/后变址、PC 相对。条件码 NZCV 在 <code>PSTATE</code>，分支可条件。缺口不是 μop ROM，而是这套<strong>程序员模型</strong>：异常级 EL0–EL3、SPSR、VBAR，对照 RISC-V 的特权与 <code>mtvec</code>。</p><p>NEON/SVE 是 SIMD/向量，后课再接。本课钉整数与系统寄存器骨架。</p><h3 id="aarch64-不是「安卓专用-isa」" tabindex="-1">AArch64 不是「安卓专用 ISA」 <a class="header-anchor" href="#aarch64-不是「安卓专用-isa」" aria-label="Permalink to &quot;AArch64 不是「安卓专用 ISA」&quot;">​</a></h3><p>它是 A-profile 64 位架构，服务器与桌面同样存在。把 ARM 当成手机品牌或 GPU，对照课会失去指令级内容。微结构（乱序宽度）与 ISA 分开，和 x86 一样。</p><p><span class="marginnote">ARM ARM 是规范。CA:AQA 用 ARM 作 RISC 例。PCS（Procedure Call Standard）是 ABI，最后一课边界再收。本课不背全部系统寄存器名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>取指对齐 4 字节，译码组合字段（比 x86 短）。<code>ldr</code>/<code>str</code> 可带扩展/移位的索引。立即数逻辑编码是特殊位模式，不是任意 32 位——编译器选 <code>mov</code> 序列。原子：<code>ldxr</code>/<code>stxr</code> 在后课 LR/SC。</p>',11)),(e(),A(n,null,{default:o(()=>[i(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20A64%5B%22%E5%AE%9A%E9%95%BF%2032%20%E4%BD%8D%22%5D%20--%3E%20GPR%5B%22X0-X30%20%2B%20XZR%22%5D%0A%20%20A64%20--%3E%20LS%5B%22load%2Fstore%20%E5%8F%98%E5%9D%80%22%5D%0A%20%20A64%20--%3E%20EL%5B%22EL0-EL3%22%5D%0A%20%20EL%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E4%B8%8E%20RISC-V%20%E5%B9%B6%E6%8E%92%E5%AF%B9%E7%85%A7%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>复位：实现定义入口，固件（TF-A）类似 UEFI 角色。GIC 对照 APIC。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>下一课明确 ARM vs RISC-V：特权、压缩、向量哲学、生态。本课只让 A64 成为可引用的 ISA，而不是「另一种 x86」。条件码相对 RISC-V 的显式比较分支是差异点，谓词课再扩。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 M-profile 微控制器，不把 TrustZone 世界切换写成完整安全课。不列每家微结构的流水线。</p><p>后课默认：AArch64 是定长 RISC 式 load/store ISA，带 NZCV 与异常级。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>A64：32 位定长、31 GPR、load/store。</li><li>异常级与系统寄存器构成特权。</li><li>前端税低于 x86 变长。</li><li>出处：ARM ARM A-profile；Hennessy and Patterson, CA:AQA。</li></ul>',8))])}const C=d(h,[["render",p]]);export{f as __pageData,C as default};
